    "utf8": "對"
  } ]
}, {
  "tStartMs": 1206388,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "所以我其實心裡"
  } ]
}, {
  "tStartMs": 1207389,
  "dDurationMs": 1652,
  "segs": [ {
    "utf8": "有一個很常的感觸就是"
  } ]
}, {
  "tStartMs": 1209041,
  "dDurationMs": 1251,
  "segs": [ {
    "utf8": "因為我從我的年代出發"
  } ]
}, {
  "tStartMs": 1210292,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "我的年代那時候東區"
  } ]
}, {
  "tStartMs": 1211693,
  "dDurationMs": 1185,
  "segs": [ {
    "utf8": "是非常繁榮的時候"
  } ]
}, {
  "tStartMs": 1212878,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "但是在我往前的那個年代"
  } ]
}, {
  "tStartMs": 1215280,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "是中山南北路非常繁華"
  } ]
}, {
  "tStartMs": 1217382,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "然後後來中山南北路就慢慢沒落"
  } ]
}, {
  "tStartMs": 1219384,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "就會變成東區 "
  } ]
}, {
  "tStartMs": 1220485,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "就現在東區沒落之後"
  } ]
}, {
  "tStartMs": 1222087,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "其實又有一點回到中山"
  } ]
}, {
  "tStartMs": 1223188,
  "dDurationMs": 1185,
  "segs": [ {
    "utf8": "回到現在赤峰街那邊 "
  } ]
}, {
  "tStartMs": 1224373,
  "dDurationMs": 717,
  "segs": [ {
    "utf8": "現在有一點"
  } ]
}, {
  "tStartMs": 1225090,
  "dDurationMs": 2503,
  "segs": [ {
    "utf8": "然後赤峰街現在整個房價又要起來"
  } ]
}, {
  "tStartMs": 1227593,
  "dDurationMs": 900,
  "segs": [ {
    "utf8": "最近的問題"
  } ]
}, {
  "tStartMs": 1228493,
  "dDurationMs": 885,
  "segs": [ {
    "utf8": "所以我去了赤峰街"
  } ]
}, {
  "tStartMs": 1229378,
  "dDurationMs": 884,
  "segs": [ {
    "utf8": "後來就跟我講說 "
  } ]
}, {
  "tStartMs": 1230262,
  "dDurationMs": 2419,
  "segs": [ {
    "utf8": "完了 下一步要往哪裡走"
  } ]
}, {
  "tStartMs": 1232681,
  "dDurationMs": 1034,
  "segs": [ {
    "utf8": "其實說真的這種 "
  } ]
}, {
  "tStartMs": 1233715,
  "dDurationMs": 1385,
  "segs": [ {
    "utf8": "就是因為它熱門了"
  } ]
}, {
  "tStartMs": 1235100,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "房價高了"
  } ]
}, {
  "tStartMs": 1235901,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "租金高了"
  } ]
}, {
  "tStartMs": 1236802,
  "dDurationMs": 600,
  "segs": [ {
    "utf8": "租金高了"
  } ]
}, {
  "tStartMs": 1237402,
  "dDurationMs": 2603,
  "segs": [ {
    "utf8": "結果原來有一些店就活不下去了"
  } ]
}, {
  "tStartMs": 1240005,
  "dDurationMs": 1084,
  "segs": [ {
    "utf8": "這個在都市裡面 "
  } ]
}, {
  "tStartMs": 1241089,
  "dDurationMs": 1218,
  "segs": [ {
    "utf8": "會一直發生一直發生"
  } ]
}, {
  "tStartMs": 1242307,
  "dDurationMs": 1952,
  "segs": [ {
    "utf8": "但如果一個市政府"
  } ]
}, {
  "tStartMs": 1244259,
  "dDurationMs": 851,
  "segs": [ {
    "utf8": " 一直讓它發生"
  } ]
}, {
  "tStartMs": 1245110,
  "dDurationMs": 1785,
  "segs": [ {
    "utf8": "你就會讓那個記憶會不見"
  } ]
}, {
  "tStartMs": 1246895,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "以前我那個東區裡面"
  } ]
}, {
  "tStartMs": 1248196,
  "dDurationMs": 1302,
  "segs": [ {
    "utf8": "看到的巷弄的一些東西 "
  } ]
}, {
  "tStartMs": 1249498,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "現在就不見了"
  } ]
}, {
  "tStartMs": 1250499,
