  "segs": [ {
    "utf8": "真的"
  } ]
}, {
  "tStartMs": 1251516,
  "dDurationMs": 2086,
  "segs": [ {
    "utf8": "但是你又不能夠直接介入說"
  } ]
}, {
  "tStartMs": 1253602,
  "dDurationMs": 1268,
  "segs": [ {
    "utf8": "我希望租金就是要凍"
  } ]
}, {
  "tStartMs": 1254870,
  "dDurationMs": 734,
  "segs": [ {
    "utf8": "這不可能"
  } ]
}, {
  "tStartMs": 1255604,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "這個在政策工具上面很難做到"
  } ]
}, {
  "tStartMs": 1257906,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "但我就發現東京"
